"""Початкові матеріали для демонстрації платформи."""
import secrets
from werkzeug.security import generate_password_hash


def seed_database(db):
    authors = [
        ('Марія Коваль', 'maria@example.test', 'Пишу про технології та наші стосунки з цифровим світом.'),
        ('Олексій Бондар', 'oleksii@example.test', 'Збираю історії про міста, книжки та маленькі відкриття.'),
        ('Софія Мельник', 'sofia@example.test', 'Досліджую культуру повсякденності та звички, які нас змінюють.'),
    ]
    ids = []
    for name, email, bio in authors:
        cursor = db.execute('INSERT INTO users(name,email,password_hash,bio) VALUES(?,?,?,?)',
                            (name, email, generate_password_hash(secrets.token_urlsafe(32)), bio))
        ids.append(cursor.lastrowid)
    stories = [
        (0, 'Менше шуму, більше сенсу: як повернути собі увагу', 'Технології', 'sage',
         'Цифровий світ просить нашої уваги щосекунди. Спробуймо обирати, чому її віддавати.',
         'Уранці рука тягнеться до телефона раніше, ніж ми встигаємо подумати про день. Новини, повідомлення, короткі відео — усе змагається за кілька хвилин. Іноді цих хвилин виявляється значно більше, ніж ми планували.\n\nУвага починається з вибору\n\nСпробуйте протягом дня помічати, навіщо відкриваєте черговий застосунок. Потрібно відповісти другові? Знайти адресу? Чи просто заповнити паузу? Усі ці причини зрозумілі, але усвідомлений вибір допомагає відчути більше контролю.\n\nМаленький експеримент\n\nВимкніть необов’язкові сповіщення на один вечір. Залиште дзвінки та повідомлення близьких. Поставте телефон подалі від робочого місця й оберіть одну справу на двадцять хвилин. Це може бути читання, приготування вечері або прогулянка.\n\nНе обов’язково відмовлятися від технологій. Можна налаштувати їх під власні потреби: прибрати зайві підписки, зберегти корисні джерела, визначити час для новин. Важливо, щоб інструмент допомагав вам, а не визначав ритм вашого дня.'),
        (1, 'Місто, яке відкривається пішки', 'Подорожі', 'peach',
         'Знайомий маршрут може стати маленькою подорожжю, якщо дозволити собі звернути за ріг.',
         'Щодня ми проходимо ті самі вулиці й часто дивимося тільки вперед. Та варто трохи сповільнитися — і знайоме місто змінюється. Над дверима з’являється стара ліпнина, у дворі чути музику, а за поворотом знаходиться маленька книгарня.\n\nМаршрут без списку пам’яток\n\nДля такої прогулянки не потрібен великий бюджет або детальний план. Оберіть район, у якому давно не були, і зручне взуття. Звертайте увагу на вивіски, дерева та те, як люди користуються простором.\n\nЗалишити собі історію\n\nЗапишіть три деталі, які вас здивували. Можна зробити фотографію, намалювати вікно або коротко описати розмову в кав’ярні. Так виникає особиста карта міста — складена з вражень, а не лише з адрес.\n\nПоважайте приватні двори та мешканців, не заходьте до небезпечних будівель. Хороша подорож починається з цікавості й уважності до людей поруч.'),
        (2, 'Читати повільно — теж навичка', 'Культура', 'lavender',
         'Чому іноді варто затриматися на одній сторінці, замість поспішати до наступної книжки.',
         'Кількість прочитаних книжок легко перетворити на змагання. Ми ставимо цілі, додаємо нові назви до списків і переживаємо, коли не вкладаємося у власний план. Але читання може бути простором, у якому немає потреби поспішати.\n\nРозмова з текстом\n\nЯкщо речення викликає запитання, зупиніться. Запишіть власну думку, поверніться до попереднього абзацу, порівняйте слова автора зі своїм досвідом. Так текст стає приводом для розмови, а не черговим завершеним завданням.\n\nЗвичка без тиску\n\nПочніть із десяти хвилин у зручний для себе час. Не обов’язково дочитувати твір, який не знаходить відгуку саме зараз. Можна повернутися до нього пізніше або обрати іншу книжку.\n\nКоли ділитеся уривками у власному блозі, зазначайте автора та назву твору. Власне враження і коректне посилання допомагають іншим читачам продовжити знайомство з текстом.'),
        (0, 'Від ідеї до першої публікації', 'Саморозвиток', 'sand',
         'Порожня сторінка лякає менше, коли не вимагати від першої чернетки досконалості.',
         'Щоб написати першу статтю, не обов’язково мати надзвичайну історію. Достатньо запитання, яке вас цікавить, або досвіду, яким хочеться поділитися. Спочатку сформулюйте одну думку: що читач має зрозуміти після прочитання?\n\nДайте чернетці бути чернеткою\n\nЗапишіть основні тези без редагування кожного речення. Додайте конкретний приклад і поясніть, чому він важливий. Якщо бракує фактів, позначте місця для перевірки, а потім поверніться до них.\n\nПеред публікацією\n\nПеречитайте текст уголос. Приберіть повтори, перевірте імена та посилання, уточніть заголовок. Відокремлюйте власний досвід від загальних тверджень. Особиста історія може бути корисною, навіть якщо вона не є універсальною порадою.\n\nЗбережіть чернетку й зробіть перерву. Свіжий погляд допомагає помітити те, що вислизало під час написання. А після публікації будьте відкритими до змістовних коментарів: вони часто підказують тему наступної статті.'),
        (2, 'Як говорити онлайн і чути одне одного', 'Суспільство', 'sky',
         'Кілька принципів розмови, у якій залишається місце для різних думок і взаємної поваги.',
         'Текстове повідомлення не передає інтонації, виразу обличчя або пауз. Через це коротка відповідь іноді здається різкою, хоча автор просто поспішав. Перед реакцією корисно перевірити, чи правильно ви зрозуміли співрозмовника.\n\nЗапитання замість припущення\n\nПопросіть пояснити думку або навести приклад. Обговорюйте конкретне твердження, уникаючи оцінок людини. Незгода стає продуктивнішою, коли учасники розуміють, у чому саме розходяться їхні позиції.\n\nМежі теж важливі\n\nВи не зобов’язані продовжувати кожну суперечку. Якщо розмова переходить до образ, можна зробити перерву або завершити її. Не публікуйте чужі особисті дані без дозволу.\n\nСпільнота формується з щоденних невеликих дій: вдячності за корисну відповідь, виправлення власної помилки, уважного читання. Коментар може не лише заперечувати, а й додавати новий погляд.'),
        (1, 'Маленькі книгарні та великі історії', 'Культура', 'peach',
         'Місця, де книжки стають початком знайомств, розмов і нових читацьких маршрутів.',
         'У невеликій книгарні цікаво спостерігати за сусідством книжок. Поруч із новим романом стоїть збірка есеїв, а на окремій полиці — видання місцевих авторів. Такий вибір багато розповідає про людей, які створили це місце.\n\nЗапитати про улюблене\n\nСпробуйте попросити не найпопулярнішу книжку, а особисту рекомендацію. Розкажіть, що вам подобалося читати раніше та якого настрою шукаєте зараз. Розмова часто виявляється не менш цікавою за покупку.\n\nМісце для зустрічі\n\nКнигарні можуть проводити читання, дискусії та зустрічі з авторами. Перед відвідуванням уточніть розклад і умови участі. Навіть якщо ви просто переглянете кілька сторінок, це вже нагода познайомитися з новою історією.\n\nПідтримувати читацьку культуру можна по-різному: відвідувати бібліотеки, обмінюватися книжками, писати чесні відгуки та радити друзям тексти, що справді вас зачепили.'),
        (0, 'Перший вебпроєкт: почати з простого', 'Технології', 'sky',
         'Як розкласти велику ідею на зрозумілі кроки й отримати перший робочий результат.',
         'Ідея власної платформи здається великою, поки не розкласти її на невеликі задачі. Почніть із головного сценарію: користувач відкриває сторінку, знаходить статтю й читає її. Лише потім додавайте наступні можливості.\n\nТри складові\n\nHTML описує структуру сторінки. CSS відповідає за вигляд і розташування елементів. JavaScript додає поведінку в браузері. Серверна частина обробляє запити та працює з даними, які мають зберігатися між відвідуваннями.\n\nПеревіряти на кожному кроці\n\nСтворивши форму, перевірте не лише правильне заповнення, а й порожні поля та завеликий текст. Додавши редагування, переконайтеся, що сторонній користувач не може змінити чужий матеріал.\n\nНевеликий проєкт із зрозумілою структурою простіше пояснити, підтримувати та розвивати. Корисно записувати рішення й причини їх вибору: ці нотатки згодом допоможуть підготувати документацію.'),
        (2, 'Нотатник для хороших запитань', 'Саморозвиток', 'sage',
         'Не всі ідеї приходять за розкладом. Як дати їм місце й помічати теми майбутніх текстів.',
         'Найкращі теми часто з’являються між справами: під час прогулянки, розмови або читання. Якщо не записати коротку думку, вона може загубитися серед інших вражень.\n\nКолекція запитань\n\nСтворіть нотатку з питаннями, на які поки не маєте відповіді. Чому певне місце викликає відчуття дому? Що змінилося у вашій роботі за останній рік? Яка звична річ заслуговує на уважніший погляд?\n\nВід запитання до тексту\n\nРаз на тиждень перегляньте записи. Оберіть один і додайте приклад із власного досвіду. Подумайте, з ким можна поговорити та які джерела перевірити. Не кожна нотатка стане статтею, і це нормально.\n\nТакий нотатник не вимагає красивого оформлення чи щоденної дисципліни. Його завдання — зберігати вашу цікавість і допомагати повертатися до думок, які мають значення.'),
    ]
    for offset, (author, title, category, cover, summary, content) in enumerate(stories):
        db.execute('''INSERT INTO articles(author_id,title,category,cover,summary,content,status,created_at)
            VALUES(?,?,?,?,?,?,'published',?)''',
                   (ids[author], title, category, cover, summary, content, f'2026-11-{5 - offset // 2:02d} 10:00:00'))
    db.commit()
